#pragma once
// (f5) The pass registry: every pass of the frame the native renderer knows, fed by the frame map.
//
// Static rows: src/native/pass-table.inc, generated by f5/mapa/mapa.py from the Ghidra frame map of 01.007.000 (the
// name string's offset in the eboot is the key: the profiler record holds that pointer). Rows the static analysis
// could not name (computed names: per-view and particle-group scopes) are added at run time by the GPU thread when
// a record's name pointer lies in the eboot image and reads as a printable string.
//
// Per-pass switch (KYTY_NATIVE_PASSES, read once): "Name:state,Name:state", state 0 emulated (default), 1 native,
// 2 verify (native and emulated both run, the outputs compared, the emulated one shown). A pass with no native
// implementation stays emulated whatever is asked, and the log says so. (f5b) In this build the only implementation is
// the verification framework's control pass (pass-verify.cpp), for any pass, in Verify only.
#include <atomic>
#include <cstddef>
#include <cstdint>

namespace NativeRender {

enum class PassState : uint8_t {
	Emulated = 0,
	Native   = 1,
	Verify   = 2,
};

enum QueueMask : uint8_t {
	QueueGraphics = 1, // DCB
	QueueCompute  = 2, // ACB
};

struct StaticPass {
	uint64_t    name_offset; // the name string's offset in the eboot (01.007.000)
	const char* name;
	uint16_t    category;     // the profiler category (ScopeBegin's third argument; 0xffff unknown)
	uint8_t     static_queues; // QueueMask seen by static analysis (signatures, waits, imports reachable)
	const char* functions;     // the game functions that open a scope with this name
};

constexpr uint32_t MaxPasses   = 256;
constexpr uint32_t NoPass      = 0xffffffffu;

class PassRegistry {
public:
	// Static rows, then the loader's base (InstallCheck). Thread: any (once, before guest threads).
	static void Init(uint64_t eboot_base, uint64_t eboot_size);
	[[nodiscard]] static bool Ready() noexcept;
	[[nodiscard]] static uint64_t EbootBase() noexcept;
	[[nodiscard]] static bool InEboot(uint64_t address) noexcept;

	// GPU thread only. The id of the pass whose name pointer is `name_ptr`; a pointer into the eboot that is not a
	// static row and reads as a name is added (dynamic). NoPass: not a name.
	[[nodiscard]] static uint32_t IdOfName(uint64_t name_ptr);

	[[nodiscard]] static uint32_t Count() noexcept;
	[[nodiscard]] static const char* Name(uint32_t id) noexcept;
	[[nodiscard]] static uint64_t NameOffset(uint32_t id) noexcept;
	[[nodiscard]] static bool IsDynamic(uint32_t id) noexcept;
	[[nodiscard]] static uint16_t Category(uint32_t id) noexcept;
	[[nodiscard]] static uint8_t StaticQueues(uint32_t id) noexcept;

	// Per-pass switch. Native / Verify only take effect when the pass has an implementation (HasNative).
	[[nodiscard]] static PassState Requested(uint32_t id) noexcept;
	[[nodiscard]] static PassState Effective(uint32_t id) noexcept;
	[[nodiscard]] static bool HasNative(uint32_t id) noexcept;

	[[nodiscard]] static const StaticPass* StaticRows(size_t* count) noexcept;
	// (f5b) Pass names as the switches write them: case, spaces and '_' ignored.
	[[nodiscard]] static bool SameName(const char* a, const char* b) noexcept;
};

} // namespace NativeRender
